import pycosat

n = 7

def var(i, j, k):
    """Variable for x[i][j] == k. 1-indexed for pycosat."""
    return i * n * n + j * n + k + 1

cnf = []

# 1. Each cell has exactly one value
for i in range(n):
    for j in range(n):
        # at least one
        cnf.append([var(i, j, k) for k in range(n)])
        # at most one
        for k1 in range(n):
            for k2 in range(k1 + 1, n):
                cnf.append([-var(i, j, k1), -var(i, j, k2)])

# 2. Idempotent diagonal
for i in range(n):
    cnf.append([var(i, i, i)])

# 3. Latin rows: each value appears exactly once per row
for i in range(n):
    for k in range(n):
        # at least one
        cnf.append([var(i, j, k) for j in range(n)])
        # at most one
        for j1 in range(n):
            for j2 in range(j1 + 1, n):
                cnf.append([-var(i, j1, k), -var(i, j2, k)])

# 4. Latin columns: each value appears exactly once per column
for j in range(n):
    for k in range(n):
        # at least one
        cnf.append([var(i, j, k) for i in range(n)])
        # at most one
        for i1 in range(n):
            for i2 in range(i1 + 1, n):
                cnf.append([-var(i1, j, k), -var(i2, j, k)])

# 5. QG3: x[x[i][j]][x[j][i]] == i
# For all i,j,a,b: if x[i][j]==a and x[j][i]==b then x[a][b]==i
# CNF: (-v[i][j][a] OR -v[j][i][b] OR v[a][b][i])
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                cnf.append([-var(i, j, a), -var(j, i, b), var(a, b, i)])

print(f"Number of variables: {n**3}")
print(f"Number of clauses: {len(cnf)}")

sol = pycosat.solve(cnf)
print(f"Result: {sol[:5] if sol != 'UNSAT' else sol}...")

